const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextToken() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        const start = pos;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            pos++;
        }
        return input.slice(start, pos);
    }

    const nStr = nextToken();
    if (!nStr) return;
    const n = parseInt(nStr, 10);

    const passwords = new Array(n);
    const freq = new Map();

    for (let i = 0; i < n; i++) {
        const s = nextToken();
        passwords[i] = s;
        freq.set(s, (freq.get(s) || 0) + 1);
    }

    let totalPairs = 0;

    for (let i = 0; i < n; i++) {
        const s = passwords[i];
        const len = s.length;
        const substrings = new Set();

        for (let start = 0; start < len; start++) {
            for (let end = start + 1; end <= len; end++) {
                substrings.add(s.slice(start, end));
            }
        }

        for (const sub of substrings) {
            const count = freq.get(sub);
            if (count !== undefined) {
                if (sub === s) {
                    totalPairs += count - 1;
                } else {
                    totalPairs += count;
                }
            }
        }
    }

    console.log(totalPairs);
}

solve();
